INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Torta de Maçã da Branca de Neve', 'DOCE', 1, 'A clássica torta de maçã, mas sem nenhum feitiço!', 'torta_maca_branca_neve.png', 4.9, '1h 15min', 'Média', 'Massa: 2 xícaras de farinha de trigo; 150g de manteiga gelada; 4 colheres (sopa) de açúcar; 1 ovo; 1 pitada de sal; Recheio: 5 maçãs vermelhas fatiadas; 1/2 xícara de açúcar mascavo; 1 colher (chá) de canela em pó; 1 colher (sopa) de suco de limão; 1 colher (sopa) de manteiga; Finalização: 1 gema para pincelar; Açúcar e canela para polvilhar', '1. Em uma tigela, misture a farinha, o açúcar e o sal. Acrescente a manteiga gelada e misture com as pontas dos dedos até formar uma farofa. Adicione o ovo e misture até obter uma massa homogênea. Embrulhe em plástico filme e leve à geladeira por 30 minutos. 2. Para o recheio, coloque as maçãs em uma panela com o açúcar mascavo, a canela, o suco de limão e a manteiga. Cozinhe por alguns minutos até as maçãs ficarem levemente macias. Reserve. 3. Abra metade da massa e forre uma forma de torta. Adicione o recheio de maçã já frio. Abra o restante da massa e faça tiras para decorar a torta em formato trançado. 4. Pincele a gema sobre a massa e polvilhe açúcar com canela por cima. Asse em forno preaquecido a 180°C por aproximadamente 40 minutos, ou até a torta ficar dourada. Sirva a torta ainda morna.'),
('Maçãs Assadas dos Sete Anões', 'DOCE', 1, 'Maçãs recheadas com amoras e mel direto do forno da cabana da floresta.', 'macas_assadas_sete_anoes.jpg', 4.8, '45min', 'Fácil', 'Maçãs recheadas: 6 maçãs vermelhas médias; 1 xícara de amoras frescas; 4 colheres (sopa) de mel; 1 colher (chá) de canela em pó; 1 colher (sopa) de manteiga em pequenos cubos; 2 colheres (sopa) de água; Decoração: Mel extra para finalizar; Folhas de hortelã; Canela em pó (opcional)', '1. Preaqueça o forno a 180°C. Lave as maçãs e retire cuidadosamente o miolo com uma faca pequena ou utensílio próprio, tomando cuidado para não atravessar a base. 2. Misture as amoras com o mel e a canela. Recheie o centro de cada maçã com essa mistura. Coloque pequenos cubinhos de manteiga sobre o recheio de cada maçã. 3. Disponha as maçãs em uma assadeira e coloque a água no fundo para ajudar a manter a umidade durante o cozimento. Leve ao forno por aproximadamente 30-35 minutos, até as maçãs ficarem macias e levemente caramelizadas. 4. Sirva ainda mornas com um fio de mel por cima e algumas folhas de hortelã.'),
('Trufas de Frozen', 'DOCE', 2, 'Trufas geladas e mágicas direto de Arendelle com efeito mesclado.', 'trufas_frozen.png', 4.8, '30min', 'Fácil', 'Casquinha: 300g de chocolate meio amargo; 200g de chocolate branco; Recheio: 1 lata de leite condensado; 200g de creme de leite; 150g de chocolate branco picado; 1 colher (chá) de essência de baunilha; Finalização: glitter comestível; flocos de açúcar; forminhas decoradas azuis e prateadas', '1. Derreta o chocolate meio amargo em banho-maria ou no micro-ondas, mexendo a cada 30 segundos. Faça o mesmo com o chocolate branco. 2. Com auxílio de uma colher, espalhe os chocolates nas formas de trufa, criando um efeito mesclado azul e marrom. Leve à geladeira por 10 minutos. 3. Para o recheio, coloque o leite condensado, o creme de leite e o chocolate branco em uma panela. Cozinhe em fogo baixo, mexendo sempre, até formar um creme firme. Finalize com a essência de baunilha. 4. Espere esfriar e recheie as casquinhas de chocolate. Cubra com mais chocolate derretido para fechar as trufas. Leve à geladeira até firmarem completamente. 5. Desenforme e finalize com glitter comestível e flocos de açúcar para lembrar o brilho de Arendelle. Sirva gelado.'),
('Cookies de Enrolados', 'DOCE', 3, 'Os biscoitos favoritos da Rapunzel e Pascal com confeitos lilás e amarelos.', 'cookies_enrolados.png', 4.7, '40min', 'Fácil', '2 xícaras de farinha de trigo; 150g de manteiga em temperatura ambiente; 3/4 de xícara de açúcar mascavo; 1/2 xícara de açúcar refinado; 1 ovo; 1 colher (chá) de essência de baunilha; 1 colher (chá) de fermento químico; 1 pitada de sal; 150g de gotas de chocolate; 50g de confeitos coloridos lilás e amarelos', '1. Em uma tigela, bata a manteiga com o açúcar mascavo e o açúcar refinado até obter um creme claro e fofo. 2. Acrescente o ovo e a essência de baunilha, misturando bem. 3. Adicione a farinha de trigo, o fermento e o sal. Misture até formar uma massa homogênea. 4. Acrescente as gotas de chocolate e os confeitos coloridos, misturando delicadamente. 5. Modele pequenas bolas de massa e distribua em uma assadeira forrada com papel manteiga, deixando espaço entre elas. 6. Leve ao forno preaquecido a 180°C por aproximadamente 15 minutos, ou até as bordas ficarem levemente douradas. Deixe esfriar por alguns minutos antes de servir em uma travessa decorada com flores.'),
('Beignet da Princesa e o Sapo', 'DOCE', 4, 'Os famosos beignets da Tiana de Nova Orleans, fofinhos e polvilhados.', 'beignet_princesa_sapo.png', 5.0, '1h', 'Média', '500g de farinha de trigo; 10g de fermento biológico seco; 1/4 de xícara de açúcar; 1 xícara de leite morno; 2 ovos; 3 colheres (sopa) de manteiga derretida; 1 colher (chá) de essência de baunilha; 1 pitada de sal; Óleo para fritar; Finalização: Açúcar de confeiteiro para polvilhar', '1. Em uma tigela, misture o leite morno, o fermento e uma colher de açúcar. Deixe descansar por 10 minutos até formar espuma. 2. Acrescente os ovos, a manteiga derretida, a baunilha e o restante do açúcar. Misture bem. 3. Adicione a farinha de trigo aos poucos junto com a pitada de sal, mexendo até formar uma massa macia. Sove a massa por alguns minutos até ficar lisa e elástica. Cubra com um pano e deixe descansar por cerca de 1 hora, até dobrar de volume. 4. Abra a massa em uma superfície enfarinhada até atingir aproximadamente 1 cm de espessura. Corte em quadrados médios. 5. Aqueça o óleo e frite os beignets até ficarem dourados dos dois lados. Retire e deixe escorrer em papel toalha. Polvilhe bastante açúcar de confeiteiro por cima enquanto ainda estiverem mornos. Sirva com café ou chocolate quente.'),
('Bolo de Café com Espiral de Canela', 'DOCE', 4, 'Bolo fofinho com efeito espiralado interno de canela e açúcar mascavo.', 'bolo_de_cafe.png', 4.9, '55min', 'Média', 'Massa: 2 xícaras de farinha de trigo; 1 xícara de açúcar; 2 colheres (chá) de fermento em pó; 1/2 colher (chá) de sal; 1/2 xícara de manteiga derretida; 2 ovos; 1 xícara de leite; 1 colher (chá) de essência de baunilha; Recheio espiral: 1/2 xícara de açúcar mascavo; 2 colheres (sopa) de canela em pó; 3 colheres (sopa) de manteiga derretida; Cobertura: Açúcar de confeiteiro para polvilhar', '1. Preaqueça o forno a 180°C e unte uma forma média. Em uma tigela, misture a farinha, o açúcar, o fermento e o sal. Acrescente a manteiga, os ovos, o leite e a baunilha. Misture até formar uma massa homogênea. 2. Em outro recipiente, misture o açúcar mascavo, a canela e a manteiga derretida. 3. Coloque metade da massa na forma. Espalhe metade da mistura de canela por cima. Cubra com o restante da massa e finalize com o restante da mistura de canela. Passe uma faca delicadamente fazendo movimentos circulares para criar o efeito espiralado dentro do bolo. 4. Leve ao forno por aproximadamente 35-40 minutos ou até dourar e o palito sair limpo. Espere esfriar levemente e polvilhe açúcar de confeiteiro antes de servir.'),
('Pão de Milho de Frigideira', 'DOCE', 4, 'Pão de milho tradicional do sul com buttermilk e um leve toque agridoce.', 'pao_de_milho.png', 4.8, '35min', 'Fácil', 'Massa: 1 xícara de farinha de milho fina; 1 xícara de farinha de trigo; 1 colher (sopa) de açúcar; 1 colher (chá) de sal; 1 colher (sopa) de fermento químico em pó; 1 ovo; 1 xícara de buttermilk (ou 1 xícara de leite com 1 colher de suco de limão/vinagre descansado por 10 minutos); 3 colheres (sopa) de manteiga derretida; Para untar: 1 colher (sopa) de manteiga', '1. Preaqueça o forno a 200°C. Coloque a frigideira (que possa ir ao forno) dentro por alguns minutos para aquecer. 2. Em uma tigela, misture a farinha de milho, farinha de trigo, açúcar, sal e fermento. Em outro recipiente, bata o ovo, acrescente o buttermilk e a manteiga derretida. 3. Junte os ingredientes líquidos aos secos e misture apenas até incorporar. 4. Retire a frigideira quente do forno, unte com manteiga e despeje a massa. 5. Leve ao forno por aproximadamente 20-25 minutos, até dourar e o topo ficar levemente firme. Faça o teste do palito. Sirva quente com manteiga.'),
('Biscoitos de Alice no País das Maravilhas', 'DOCE', 5, 'Biscoitos amanteigados em formatos divertidos decorados com glacê real.', 'biscoitos_alice.png', 4.6, '45min', 'Média', '2 xícaras de farinha de trigo; 150g de manteiga em temperatura ambiente; 3/4 de xícara de açúcar; 1 ovo; 1 colher (chá) de essência de baunilha; 1 colher (chá) de fermento químico; 1 pitada de sal; Decoração: Glacê colorido azul, rosa e lilás; Confeitos coloridos; Corante alimentício; Caneta culinária para detalhes', '1. Em uma tigela, bata a manteiga com o açúcar até formar um creme claro e fofo. Acrescente o ovo e a essência de baunilha, misturando bem. 2. Adicione a farinha de trigo, o fermento e o sal. Misture até formar uma massa homogênea. Embrulhe a massa em plástico filme e leve à geladeira por 30 minutos. 3. Abra a massa em uma superfície enfarinhada e corte os biscoitos com formatos divertidos, como cartas, relógios, xícaras ou corações. 4. Coloque os biscoitos em uma assadeira forrada com papel manteiga e asse em forno preaquecido a 180°C por aproximadamente 12 a 15 minutos. Espere esfriar completamente antes de decorar com os glacês coloridos e os confeitos. Use a caneta culinária para os detalhes do Chá Maluco.'),
('Bolo de Lilo & Stitch', 'DOCE', 7, 'Bolo azul do Stitch com recheio cremoso de coco tropical.', 'bolo_lilo.png', 5.0, '1h', 'Média', 'Massa: 3 ovos; 2 xícaras de farinha de trigo; 1 e 1/2 xícara de açúcar; 1/2 xícara de óleo; 1 xícara de leite; 1 colher (sopa) de fermento químico; 1 colher (chá) de essência de baunilha; Recheio: 1 lata de leite condensado; 200ml de leite de coco; 100g de coco ralado; 1 colher (sopa) de manteiga; Cobertura: 400g de chantilly; Corante alimentício azul; Confeitos tropicais ou flores de açúcar', '1. Em uma tigela, bata os ovos com o açúcar até formar um creme claro. Acrescente o óleo, o leite e a essência de baunilha, misturando bem. Adicione a farinha de trigo aos poucos e finalize com o fermento. Despeje a massa em uma forma untada e asse em forno preaquecido a 180°C por aproximadamente 40 minutos. 2. Para o recheio, coloque o leite condensado, o leite de coco, o coco ralado e a manteiga em uma panela. Cozinhe em fogo baixo até formar um creme consistente. Deixe esfriar. 3. Corte o bolo ao meio e recheie com o creme de coco. 4. Bata o chantilly e misture o corante azul até obter a cor do Stitch. Cubra todo o bolo e decore com as flores tropicais e confeitos do Havaí. Sirva gelado.'),
('Crisp de Frutas Vermelhas da Aurora', 'DOCE', 8, 'Frutas vermelhas assadas com uma incrível e aromática cobertura de aveia crocante.', 'Crisp_de_Frutas.png', 4.8, '40min', 'Fácil', 'Frutas: 2 xícaras de morangos picados; 1 xícara de framboesas; 1 xícara de amoras; 1/2 xícara de açúcar; 1 colher (sopa) de suco de limão; 1 colher (chá) de essência de baunilha; Cobertura crocante: 1 xícara de farinha de trigo; 3/4 de xícara de aveia em flocos; 1/2 xícara de açúcar mascavo; 100g de manteiga gelada em cubos; 1 pitada de canela', '1. Em uma tigela, misture os morangos, as framboesas, as amoras, o açúcar, o suco de limão e a essência de baunilha. Coloque as frutas em um refratário untado. 2. Para a cobertura, misture a farinha, a aveia, o açúcar mascavo e a canela. Acrescente a manteiga gelada e misture com as pontas dos dedos até formar uma farofa úmida. 3. Espalhe a cobertura sobre as frutas vermelhas. 4. Leve ao forno preaquecido a 180°C por aproximadamente 30 minutos, ou até a superfície ficar dourada e crocante. Retire do forno, deixe descansar alguns minutos e sirva morno acompanhado de sorvete de creme.'),
('Pipoca Rosa da Aurora', 'DOCE', 8, 'Pipoca doce macia envolvida em uma calda cremosa de marshmallow e morango.', 'pipoca_da_bela.png', 4.7, '15min', 'Fácil', 'Pipoca: 1/2 xícara de milho para pipoca; 2 colheres (sopa) de óleo; Calda Rosa Encantada: 200g de marshmallows; 3 colheres (sopa) de manteiga; 1 pacote de gelatina sabor morango; 3 colheres (sopa) de leite; Decoração: Confeitos coloridos; Glitter comestível rosa (opcional); Mini marshmallows (opcional)', '1. Estoure a pipoca normalmente em uma panela com óleo. Retire os grãos que não estouraram e reserve a pipoca em uma tigela grande. 2. Em fogo baixo, derreta a manteiga e adicione os marshmallows, mexendo até formar um creme liso. Acrescente a gelatina de morango e o leite, misturando bem até a cor ficar uniforme e rosa brilhante. 3. Despeje a calda sobre a pipoca aos poucos, mexendo delicadamente para envolver tudo. 4. Espalhe a pipoca em uma assadeira forrada com papel-manteiga e deixe esfriar alguns minutos. Finalize com confeitos e mini marshmallows.'),
('Mousse Crocante do Russell', 'DOCE', 9, 'Mousse cremosa de chocolate com uma camada crocante de cereal e castanhas.', 'mousse_de_chocolate.png', 4.9, '30min', 'Fácil', 'Base: 1 lata de leite condensado; 2 caixas de creme de leite; 200g de chocolate ao leite derretido; 1 envelope de gelatina sem sabor; 5 colheres (sopa) de água; 1 colher (chá) de essência de baunilha; Crocante: 1 xícara de cereal de chocolate; 1/2 xícara de castanhas picadas; 100g de chocolate meio amargo derretido; Decoração: Mini marshmallows; Raspas de chocolate; Confeitos coloridos', '1. Hidrate a gelatina sem sabor na água e dissolva conforme as instruções da embalagem. 2. No liquidificador, bata o leite condensado, o creme de leite, o chocolate ao leite derretido, a essência de baunilha e a gelatina dissolvida até obter um creme liso. Distribua a mousse em taças ou potinhos e leve à geladeira por aproximadamente 3 horas. 3. Para o crocante, misture o cereal de chocolate e as castanhas com o chocolate meio amargo derretido. Espalhe em uma assadeira forrada com papel manteiga e deixe endurecer. Depois, quebre em pedaços pequenos. 4. Finalize a mousse adicionando o crocante por cima. Decore com mini marshmallows, raspas de chocolate e confeitos coloridos.'),
('Mousse de Banana e Manga do Mogli', 'DOCE', 10, 'Sobremesa refrescante e tropical batida no liquidificador com frutas frescas.', 'mousse_banana.png', 4.7, '20min', 'Fácil', '2 bananas maduras; 1 manga grande picada; 1 lata de leite condensado; 1 caixa de creme de leite; 1 envelope de gelatina sem sabor; 5 colheres (sopa) de água; 1 colher (chá) de essência de baunilha; Suco de 1/2 limão; Decoração: Banana em rodelas; Cubinhos de manga; Folhas de hortelã; Coco ralado', '1. Hidrate a gelatina sem sabor na água e dissolva conforme as instruções da embalagem. 2. No liquidificador, bata as bananas, a manga, o leite condensado, o creme de leite, a essência de baunilha e o suco de limão até obter um creme homogêneo. 3. Acrescente a gelatina dissolvida e bata novamente por alguns segundos. 4. Distribua a mousse em taças ou potinhos individuais e leve à geladeira por aproximadamente 3 horas, até firmar bem. Finalize decorando com as rodelas de banana, cubinhos de manga, coco ralado e folhas de hortelã.'),
('Palmiers da Minnie', 'DOCE', 11, 'Massa folhada crocante envolta em açúcar e canela com acabamento de chocolate.', 'palmire_minnie.png', 4.9, '45min', 'Média', '1 pacote de massa folhada pronta; 1/2 xícara de açúcar; 1 colher (chá) de canela em pó; 100g de chocolate meio amargo derretido; Decoração: Confeitos vermelhos, pretos e brancos; Glacê branco; Mini confeitos em formato de coração ou bolinhas', '1. Abra a massa folhada em uma superfície lisa. Misture o açúcar com a canela e espalhe sobre toda a massa. 2. Enrole as duas extremidades da massa em direção ao centro até que se encontrem no meio, formando o clássico formato de palmier. Leve à geladeira por 15 minutos para facilitar o corte. 3. Corte fatias de aproximadamente 1 cm e coloque em uma assadeira forrada com papel manteiga. 4. Asse em forno preaquecido a 200°C por cerca de 15 a 20 minutos, até ficarem dourados e crocantes. Depois de frios, mergulhe parte dos palmiers no chocolate derretido e decore com os confeitos coloridos da Minnie.'),
('As Trutas da Mérida', 'DOCE', 12, 'Massa doce em formato de peixe das terras escocesas.', 'trutas_merida.png', 4.6, '50min', 'Média', 'Massa doce;Recheio de maçã', 'Modele como peixes e asse até dourar.'),
('Os Palmiers da Clarabela', 'DOCE', 11, 'Biscoito folhado de açúcar tradicional.', 'clarabela_doce.jpg', 4.5, '35min', 'Fácil', 'Massa folhada;Açúcar cristal', 'Enrole, corte e asse.'),
('Madeleines do Pooh', 'DOCE', 13, 'Tradicionais bolinhos franceses aerados e fofinhos regados com fios de mel puro.', 'ursinho_pu.png', 5.0, '30min', 'Média', '2 ovos; 1/2 xícara de açúcar; 1 colher (chá) de essência de baunilha; 1 colher (sopa) de mel; 1 xícara de farinha de trigo; 1 colher (chá) de fermento químico; 100g de manteiga derretida; 1 pitada de sal; Decoração: Mel para finalizar; Açúcar de confeiteiro; Flores comestíveis opcionais', '1. Em uma tigela, bata os ovos com o açúcar até obter um creme claro e fofo. Acrescente a essência de baunilha e o mel, misturando delicadamente. 2. Adicione a farinha de trigo, o fermento e a pitada de sal. Misture até incorporar. Acrescente a manteiga derretida aos poucos, mexendo até formar uma massa lisa. 3. Cubra a massa e leve à geladeira por 30 minutos para deixar as madeleines mais macias. 4. Distribua a massa em formas próprias para madeleine untadas. Asse em forno preaquecido a 180°C por aproximadamente 10 a 12 minutos, até ficarem douradinhas nas bordas. Espere amornar e finalize com fios de mel e açúcar de confeiteiro.'),
('Varinhas Mágicas Bibbidi-Bobbidi-Boo', 'DOCE', 26, 'Tiras de tortilhas assadas em formato de estrela com açúcar cristal colorido.', 'varinhas_magicas.png', 4.8, '20min', 'Fácil', 'Varinhas: 4 tortilhas médias; 3 colheres (sopa) de manteiga derretida; 4 colheres (sopa) de açúcar cristal; Corante alimentício colorido (azul, rosa ou lilás); 1 colher (chá) de canela (opcional); Decoração: Glitter comestível; Confeitos em formato de estrelas; Açúcar colorido; Chocolate branco derretido (opcional)', '1. Preaqueça o forno a 180°C. Corte as tortilhas em tiras compridas e, em uma das pontas, faça pequenas estrelas usando uma faca ou molde pequeno. Pincele todas as tiras com manteiga derretida. 2. Misture o açúcar com algumas gotas de corante alimentício até formar cristais coloridos (adicione canela se desejar). Polvilhe esse açúcar sobre as tortilhas. 3. Coloque em uma forma com papel-manteiga e leve ao forno por cerca de 8-12 minutos, até ficarem douradas e crocantes. Espere esfriar e finalize com chocolate branco derretido e confeitos de estrelas. Sirva em copinhos com as estrelas para cima.'),
('Barrinhas de Cereal do Flecha', 'DOCE', 24, 'Barrinhas energéticas e crocantes de granola com damascos secos e castanhas.', 'barrinha_da_flecha.png', 4.8, '30min', 'Fácil', 'Base: 2 xícaras de granola; 4 colheres (sopa) de mel; 3 colheres (sopa) de manteiga; 1/2 xícara de damascos secos picados; 1/2 xícara de castanhas picadas; 1/4 de xícara de frutas cristalizadas picadas; 1 colher (chá) de essência de baunilha; Decoração: Fios de mel; Chocolate derretido para decorar; Pedacinhos extras de castanhas', '1. Preaqueça o forno a 180°C. Em uma panela pequena, aqueça a manteiga com o mel até derreter e formar uma mistura homogênea. Acrescente a baunilha. 2. Em uma tigela grande, misture a granola, os damascos, as castanhas e as frutas cristalizadas. Despeje a mistura líquida por cima e mexa bem. 3. Transfira para uma forma pequena forrada com papel-manteiga, pressionando bem com uma colher para compactar. 4. Leve ao forno por aproximadamente 15-20 minutos, até dourar levemente. Espere esfriar completamente antes de cortar em formato de barrinhas e finalizar com fios de mel ou chocolate derretido.'),
('Salada de Laranjas da Jasmine', 'DOCE', 23, 'Laranjas frescas fatiadas regadas com uma calda aromática de mel e flor de laranjeira.', 'salada_jasmin.png', 4.7, '25min', 'Fácil', 'Salada: 4 laranjas grandes; 1/4 de xícara de pistaches picados; Folhas frescas de hortelã a gosto; Calda aromática: 2 colheres (sopa) de mel; 1 colher (chá) de água de flor de laranjeira; 1 colher (sopa) de suco de laranja; Decoração: Pistaches extras; Folhinhas pequenas de hortelã; Raspas finas de casca de laranja', '1. Descasque as laranjas retirando toda a parte branca e corte-as em rodelas ou em gomos. 2. Em um recipiente pequeno, misture o mel, a água de flor de laranjeira e o suco de laranja. 3. Disponha as laranjas em uma travessa ou taças individuais e regue com a calda aromática. 4. Polvilhe os pistaches picados e as folhas de hortelã por cima. Leve à geladeira por cerca de 15 minutos antes de servir para ficar refrescante e decore com as raspas de laranja.'),
('Bananas do Rafiki', 'DOCE', 27, 'Bananas assadas na casca e regadas com uma calda cítrica de xarope de bordo.', 'bananas_do_rafiki.png', 4.6, '25min', 'Fácil', 'Bananas: 4 bananas maduras (mas ainda firmes); 2 colheres (sopa) de xarope de bordo (maple syrup); Suco de 1 limão; Raspas de 1 limão; 1 colher (sopa) de manteiga derretida; Decoração: Canela em pó (opcional); Folhas de hortelã; Castanhas picadas (opcional)', '1. Preaqueça o forno a 200°C. Corte as bananas ao meio no sentido do comprimento, mantendo a casca. 2. Coloque as bananas em uma assadeira com a parte cortada voltada para cima. 3. Em uma tigela pequena, misture o xarope de bordo, o suco de limão, as raspas e a manteiga derretida. Regue generosamente as bananas com essa calda. 4. Leve ao forno por aproximadamente 15-20 minutos, até as bananas ficarem macias e levemente douradas. Sirva quentinhas com canela, hortelã e castanhas por cima.');
INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Ratatouille', 'SALGADO', 6, 'O clássico prato camponês que derreteu o coração do crítico.', 'ratatouille.png', 5.0, '1h 30min', 'Difícil', '1 abobrinha em rodelas; 1 berinjela em rodelas; 2 tomates em rodelas; 1 pimentão amarelo em rodelas; 1 cebola roxa fatiada; 2 dentes de alho; Molho de tomate; Azeite; Sal, Pimenta e Ervas finas.', '1. Espalhe molho de tomate no fundo de uma travessa. 2. Refogue a cebola e alho no azeite e misture ao molho. 3. Organize as rodelas de legumes alternadamente em formato circular. 4. Tempere, regue com azeite e asse a 180°C coberto com papel-alumínio por 40 min. 5. Retire o papel e asse por mais 15 min. Decore com manjericão.'),
('Arepas con queso de Encanto', 'SALGADO', 14, 'Arepas curativas feitas com amor pela Julieta Madrigal.', 'arepas_encanto.png', 4.9, '30min', 'Fácil', '2 xícaras de farinha de milho pré-cozida; 2 xícaras de água morna; 1 colher (sopa) de manteiga derretida; 1 xícara de muçarela ralada; 1/2 xícara de parmesão; Sal.', '1. Misture água morna, sal e manteiga. 2. Adicione a farinha de milho aos poucos até formar uma massa macia. 3. Misture os queijos na massa e deixe descansar. 4. Modele discos e grelhe na frigideira com manteiga até dourar. 5. Finalize no forno por 10 min.'),
('Macarrão ao molho pesto de Luca', 'SALGADO', 15, 'Trenette al pesto, perfeito para um dia em Portorosso.', 'macarrao_pesto_luca.png', 4.8, '25min', 'Fácil', '500g de macarrão Trenette; 2 xícaras de manjericão fresco; 1/2 xícara de azeite; 2 dentes de alho; 50g de parmesão; 2 colheres (sopa) de pinolis ou nozes; 1 batata média em cubos; 100g de vagem; Sal a gosto.', '1. No liquidificador, bata o manjericão, alho, pinolis, azeite e queijo até formar um pesto. 2. Ferva água com sal e cozinhe a batata e a vagem. 3. Adicione o macarrão na mesma água e cozinhe. 4. Escorra (reserve um pouco da água). 5. Misture a massa e legumes com o pesto, usando a água do cozimento para dar cremosidade.'),
('Espaguete com Almôndegas da Dama e o Vagabundo', 'SALGADO', 16, 'O prato mais romântico da Itália canina.', 'espaguete_almondegas.png', 4.9, '50min', 'Média', '500g de espaguete; 500g de carne moída; 1 ovo; Cebola; Alho; 1/2 xícara de farinha de rosca; 1 sachê de molho de tomate; Manjericão e Parmesão.', '1. Misture carne, ovo, cebola, alho e farinha de rosca. Modele almôndegas e doure na frigideira. 2. Refogue cebola e alho para o molho, adicione tomate e manjericão. 3. Cozinhe as almôndegas no molho por 10 min. 4. Misture com o espaguete cozido e polvilhe queijo.'),
('Cenouras com Molho de Laranja da Judy Hopps', 'SALGADO', 17, 'Rápido e prático para policiais de Zootopia.', 'cenoura_zootopia.png', 4.8, '20min', 'Fácil', '4 cenouras médias em palitos; 1 colher (sopa) de manteiga; Suco de 2 laranjas; 1 colher (sopa) de mel; Sal e salsinha.', '1. Cozinhe as cenouras até ficarem levemente macias. 2. Derreta manteiga na frigideira, adicione suco de laranja e mel. 3. Misture as cenouras ao molho e deixe caramelizar. Finalize com salsinha.'),
('Beringelas Recheadas à Ratatouille', 'SALGADO', 6, 'Uma variação vegetariana do prato do Remy.', 'beringela_ratatouille.png', 4.9, '50min', 'Média', '2 berinjelas grandes; 1 abobrinha em cubos; 2 tomates picados; 1/2 pimentão picado; 1/2 cebola; 2 dentes de alho; Molho de tomate; Queijo muçarela.', '1. Corte as berinjelas ao meio, retire a polpa e asse as barquinhas a 180°C por 15 min. 2. Refogue cebola, alho, polpa da berinjela, abobrinha, tomate e pimentão. 3. Adicione molho de tomate e ervas. 4. Recheie as berinjelas, cubra com muçarela e gratine no forno.'),
('Chorizo Refogado do Hector', 'SALGADO', 18, 'Um aperitivo que vai te fazer lembrar de mim.', 'chorizo_hector.png', 4.8, '25min', 'Fácil', '300g de chorizo em rodelas; 1 cebola roxa fatiada; 1 pimentão vermelho; 2 dentes de alho; 1 tomate picado; Azeite e cheiro-verde.', '1. Refogue o alho e cebola no azeite. 2. Adicione o chorizo e doure bem. 3. Junte o pimentão e o tomate, cozinhando até ficarem macios. Sirva com tortilhas e limão.'),
('Cogumelos Recheados do Pateta', 'SALGADO', 11, 'Um aperitivo delicioso e divertido.', 'cogumelo_pateta.png', 4.5, '30min', 'Média', '12 cogumelos grandes; 100g de cream cheese; 50g de parmesão; Manteiga; Cebola; Alho; Farinha de rosca.', '1. Retire os cabos dos cogumelos e pique-os. 2. Refogue os cabos com cebola e alho na manteiga. 3. Misture com cream cheese e parmesão. 4. Recheie os cogumelos, polvilhe farinha de rosca e asse a 180°C por 20 min.'),
('Jantar Leve da Duquesa', 'SALGADO', 19, 'Uma terrine de atum elegante para gatos da alta sociedade.', 'terrineatum_duquesa.png', 4.7, '40min', 'Média', '2 latas de atum; 1 creme de leite; 1 copo de requeijão; 1 cenoura ralada; Cebola; Gelatina incolor sem sabor.', '1. Misture atum, creme de leite, requeijão e legumes. 2. Hidrate a gelatina e misture ao creme. 3. Despeje numa forma e leve à geladeira por 4 horas para firmar. Sirva com torradas.'),
('Sopa da Floresta do Dunga', 'SALGADO', 1, 'Caldo quentinho perfeito para depois do trabalho.', 'sopa_floresta.png', 4.6, '1h', 'Fácil', 'Batatas; Cenouras; Chuchu; Abobrinha; Cebola; Alho; 1 litro de caldo de legumes.', '1. Refogue alho e cebola no azeite. 2. Acrescente os legumes picados e o caldo. 3. Cozinhe até macios. Bater parte no liquidificador para engrossar se desejar.'),
('Peixe à Tropical da Moana', 'SALGADO', 20, 'Ceviche marinado com o frescor do oceano.', 'peixe_moana.png', 5.0, '20min', 'Média', '500g de peixe branco fresco; Suco de 4 limões; 1 manga em cubinhos; Cebola roxa; Tomate; Pimentão amarelo; Coentro.', '1. Cubra o peixe com suco de limão e marine por 20-30 min. 2. Escorra o líquido e misture com a manga e os legumes picados. 3. Tempere com azeite, sal e coentro. Sirva gelado.'),
('Saltimboccas do Pinóquio', 'SALGADO', 21, 'Prato italiano de verdade para um menino de verdade.', 'saltimboccas_pinoquio.png', 4.9, '35min', 'Média', '4 bifes finos; 4 fatias de presunto; 4 fatias de muçarela; Folhas de sálvia; Manteiga.', '1. Coloque presunto, muçarela e sálvia sobre cada bife. 2. Enrole os bifes e prenda com palitos. 3. Doure os rolinhos na manteiga com azeite até cozinhar por dentro. Regue com a manteiga.'),
('Petiscos do Pongo', 'SALGADO', 22, 'Rolinhos de carne moída irresistíveis.', 'petisco_pongo.png', 4.8, '45min', 'Fácil', '500g de carne moída; 1 ovo; Farinha de rosca; Muçarela; Fatias de bacon; Temperos.', '1. Misture a carne moída, ovo, farinha e temperos. 2. Modele discos, coloque queijo no centro e enrole. 3. Envolva cada rolinho com bacon. 4. Asse a 200°C por 30 min.'),
('A Caçarola do Patinho Fofinho', 'SALGADO', 3, 'Prato rústico direto da taverna.', 'cassarola_enrolados.png', 4.7, '1h 20min', 'Difícil', '500g de carne bovina em cubos; 2 colheres (sopa) de farinha de trigo; Cebola; Alho; 2 cenouras; 2 batatas; 1 litro de caldo de carne; Extrato de tomate; Temperos.', '1. Empane a carne na farinha e doure bem no azeite. 2. Refogue a cebola e alho, junte o extrato de tomate. 3. Volte a carne, adicione os legumes e o caldo. 4. Tampe e cozinhe em fogo baixo por 1 hora até a carne desmanchar e o caldo engrossar.'),
('Enroladinhos de Tapete Mágico', 'SALGADO', 23, 'Aperitivos das arábias com a Princesa Jasmine.', 'tapetes_magicos.png', 4.8, '30min', 'Fácil', '6 massas de wrap (pão folha); 300g de frango desfiado; 150g de muçarela; 1 colher (sopa) de requeijão; Cenoura ralada; Temperos.', '1. Misture o frango desfiado com requeijão e cenoura. 2. Abra a massa, espalhe queijo e coloque o recheio. 3. Enrole firme e toste em uma frigideira até o queijo derreter e a massa ficar crocante.'),
('Super Bife da Família Parr', 'SALGADO', 24, 'Apenas para super-heróis com muita fome.', 'super_bife.png', 5.0, '25min', 'Fácil', '4 bifes grandes de contrafilé ou ancho; 2 colheres (sopa) de manteiga; Alho amassado; Azeite; Sal grosso; Alecrim.', '1. Tempere os bifes com sal grosso. 2. Numa chapa quente, sele os bifes por 3-4 minutos de cada lado. 3. Adicione manteiga, alho e alecrim na panela e regue os bifes constantemente para suculência.'),
('Chips Crocantes da Mulan', 'SALGADO', 25, 'Lanchinho rápido para quem vai salvar o dia.', 'chips_mulan.png', 4.6, '20min', 'Fácil', '2 batatas-doces; 2 colheres (sopa) de azeite; 1 colher (chá) de páprica; Sal e pimenta.', '1. Preaqueça o forno a 200°C. 2. Fatie as batatas bem finas (tipo chips). 3. Misture com o azeite, sal e páprica. 4. Espalhe em uma assadeira sem sobrepor e asse por 15-20 minutos, virando na metade, até ficarem bem crocantes.'),
('Espaguete dos Aristogatas', 'SALGADO', 19, 'Macarrão com muito queijo, monsieur.', 'espaguetes_aristogatas.png', 4.9, '30min', 'Fácil', '500g de espaguete; 2 colheres (sopa) de manteiga; Cebola; Alho; Creme de leite; Parmesão; Muçarela; Noz-moscada.', '1. Cozinhe a massa. 2. Refogue cebola e alho na manteiga. 3. Adicione o creme de leite, os queijos e a noz-moscada. 4. Misture a massa no molho e sirva com parmesão e manjericão.'),
('Empanada Preferida do Miguel', 'SALGADO', 18, 'Empanadas crocantes e recheadas com carne e muito queijo.', 'empanada_miguel.png', 4.9, '50min', 'Média', 'Massa: 3 xícaras de farinha; 100g de manteiga; 1 ovo; Água. Recheio: 300g de carne moída; 150g de muçarela; Cebola; Alho; Cominho; Páprica.', '1. Misture a farinha, manteiga, ovo e água para formar a massa. Descanse 20 min. 2. Refogue a carne com temperos e depois misture a muçarela. 3. Abra a massa em círculos, recheie, feche apertando com garfo. 4. Pincele gema e asse a 180°C por 30 min.'),
('Tortellini do Gepeto', 'SALGADO', 21, 'Massa italiana artesanal com copa e pinolis.', 'tortellini_gepeto.png', 4.9, '20min', 'Fácil', '500g de tortellini de ricota; 100g de copa (coppa); Pinolis; Manjericão fresco; Azeite e Alho.', '1. Cozinhe o tortellini. 2. Aromatize o azeite com alho e retire. Toste os pinolis rapidamente e doure a copa. 3. Misture a massa e finalize com manjericão fresco.'),
('Creme de Abobrinha do Kaa', 'SALGADO', 10, 'Creme liso e brilhante, hipnotizante como Kaa.', 'creme_abobrinha_kaa.png', 4.7, '30min', 'Fácil', '2 abobrinhas; 1 batata; 500ml de caldo de legumes; 200g de creme de leite; Manteiga; Noz-moscada.', '1. Refogue cebola, alho, abobrinha e batata. 2. Adicione caldo e cozinhe até ficar macio. 3. Bata no liquidificador e volte ao fogo misturando com creme de leite. Decore com espirais de azeite.'),
('Sanduíches Saborosas da Tiana', 'SALGADO', 4, 'Lanches florais e super delicados.', 'sanduiche_tiana.jpg', 4.8, '15min', 'Fácil', 'Fatias de pão branco e integral; Queijo prato; Fiambre; Maionese; Alho em pó; Páprica.', '1. Misture a maionese com os temperos e passe no pão. 2. Monte os sanduíches intercalando queijo e fiambre. 3. Use um cortador de flores para dar formato e servir elegante.'),
('Porco com Abacaxi', 'SALGADO', 4, 'Bifes de porco caramelizados ao molho agridoce.', 'porco_com_abacaxi.png', 4.9, '30min', 'Média', '4 bifes de porco; 6 rodelas de abacaxi em calda; Shoyu; Mel; Amido de milho.', '1. Tempere e doure a carne na frigideira. Reserve. 2. Doure o abacaxi na mesma panela. 3. Volte a carne, acrescente shoyu, a calda do abacaxi e engrosse com amido de milho.'),
('Salada de Outono', 'SALGADO', 33, 'Salada refrescante com o frescor da natureza.', 'salada_outono.png', 4.6, '15min', 'Fácil', 'Alface; Uvas pretas; Nozes picadas; Queijo branco; Óleo de nozes; Vinagre balsâmico; Mel.', '1. Monte a salada numa travessa com a alface, uvas e nozes. 2. Prepare o molho misturando óleo de nozes, vinagre e mel. Regue delicadamente.'),
('Espiga de Milho do John Smith', 'SALGADO', 33, 'Milho temperado ao estilo desbravador.', 'espiga_john.png', 4.7, '25min', 'Fácil', '4 espigas de milho; Manteiga; Curry; Páprica doce; Queijo feta ou parmesão.', '1. Cozinhe as espigas. 2. Misture a manteiga derretida com os temperos. 3. Pincele o milho quente e polvilhe o queijo por cima.'),
('Batata-Doce Assada no Forno', 'SALGADO', 33, 'Palitos de batata-doce rústicos com molho caseiro.', 'batata_doce_pocah.png', 4.8, '45min', 'Média', '3 batatas-doces; Azeite; Páprica; Sal; Para o molho: Tomates, pimentão, mel, alho.', '1. Corte as batatas em palitos, tempere com azeite e páprica e asse a 200°C por 40 min. 2. Bata os ingredientes do molho caseiro e sirva junto com os palitos crocantes.'),
('Galetes de Milho', 'SALGADO', 33, 'Tortinhas redondas e douradinhas de milho.', 'galete_milho.jpg', 4.6, '20min', 'Fácil', '2 xícaras de milho-verde; 2 ovos; 1/2 xícara de farinha; Leite; Parmesão.', '1. Bata metade dos ingredientes no liquidificador. 2. Incorpore a farinha e parmesão. 3. Frite pequenas porções da massa numa frigideira quente até dourarem de ambos os lados.'),
('O Ceviche do Imperador', 'SALGADO', 35, 'Ceviche refrescante servido em barquetes de pepino.', 'ceviche_do_imperador.png', 5.0, '25min', 'Fácil', '400g de peixe branco em cubos; Suco de 4 limões; 100ml de leite de coco; Coentro; 2 pepinos grandes.', '1. Marine o peixe no limão e leite de coco. 2. Misture cebola, coentro e azeite. 3. Corte os pepinos ao meio, tire as sementes para formar barquetes e recheie com o ceviche.'),
('Mac and Cheeseburger', 'SALGADO', 26, 'A fusão perfeita do macarrão com queijo e a suculência da carne.', 'mac_and_cheeseburguer.png', 4.9, '45min', 'Média', '300g de macarrão cotovelo; 300g de carne moída; Manteiga; Farinha; Leite; Queijo cheddar e parmesão.', '1. Cozinhe o macarrão e refogue a carne moída. 2. Faça um molho branco espesso e derreta os queijos. 3. Misture tudo, coloque numa travessa, cubra com mais queijo e gratine no forno.'),
('Frango da Wendy', 'SALGADO', 36, 'Um assado delicioso em uma cama de vegetais.', 'frango_wendy.png', 4.8, '1h15min', 'Média', '1 frango inteiro (1,5kg); Molho pesto; Azeite; Brócolis; Couve-romanesco; Cebola; Tomilho.', '1. Tempere o frango e pincele o molho pesto inclusive debaixo da pele. 2. Distribua os vegetais no fundo da assadeira. 3. Coloque o frango por cima e asse a 200°C até dourar e cozinhar bem.'),
('A Torta do Merlin', 'SALGADO', 34, 'Torta rústica com massa quebradiça e recheio robusto.','torta_merlin.jpg', 4.9, '1h', 'Média', 'Massa: Farinha, manteiga, água gelada. Recheio: Carne moída, linguiça, batatas picadas, tomilho.', '1. Prepare a massa esfarelando manteiga e farinha, misture com água gelada e reserve. 2. Refogue a carne, linguiça e batata com tomilho. 3. Recheie a torta, feche, pincele gema e asse.'),
('Copinhos de Salada de Frango Defumado', 'SALGADO', 37, 'Copinhos refrescantes de alface romana com salada cremosa de frango defumado e amêndoas, dignos do Olimpo.', 'copinhos_de_salada.png', 4.9, '20min', 'Fácil', '2 xícaras de peito de frango assado e desfiado; 3 colheres (sopa) de maionese; 1 talo de aipo cortado em fatias finas; 2 colheres (sopa) de cebolinho picado; 1/2 pimentão vermelho assado e picado; 1/4 de xícara de amêndoas defumadas picadas; 1 colher (chá) de páprica defumada; Sal e Pimenta-do-reino; 8 folhas inteiras de alface romana.', '1. Em uma tigela grande, misture o frango desfiado, a maionese, o aipo, o cebolinho e o pimentão assado. 2. Acrescente as amêndoas defumadas e a páprica defumada. 3. Tempere com sal e pimenta a gosto e misture bem até incorporar todos os ingredientes. 4. Lave e seque cuidadosamente as folhas de alface romana. 5. Coloque porções da salada dentro das folhas, forming pequenos copinhos. 6. Finalize com cebolinho extra, amêndoas picadas e uma leve pitada de páprica defumada. Sirva gelado.');
INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Super Suco para dar Energia', 'BEBIDA', 24, 'Uma bebida refrescante, saudável e perfeita para começar o dia como um super-herói.', 'suco_energia.png', 5.0, '10min', 'Fácil', '2 laranjas espremidas; 1 cenoura picada; 1 maçã vermelha picada; 1 banana; 300ml de água gelada; 1 colher (sopa) de mel; Gelo a gosto; Opcional: Folhas de hortelã e Sementes de chia.', '1. Coloque no liquidificador o suco das laranjas, a cenoura, a maçã e a banana. 2. Acrescente a água gelada, o mel e algumas pedras de gelo. 3. Bata tudo até obter uma bebida cremosa e homogênea. 4. Se desejar, adicione chia para deixar o suco ainda mais nutritivo. 5. Sirva imediatamente e decore com folhas de hortelã.'),
('Suco das Ilhas', 'BEBIDA', 7, 'Bebida cremosa, refrescante e cheia de sabores das ilhas, perfeita para dias quentes.', 'suco_ilha.png', 4.9, '10min', 'Fácil', '1 xícara de polpa de manga; 200ml de leite de coco; 300ml de suco de abacaxi; 3 colheres (sopa) de xarope de groselha; 1 xícara de gelo; Decoração: Carambola, manga e cerejas.', '1. Coloque no liquidificador a polpa de manga, o leite de coco, o suco de abacaxi, a groselha e o gelo. 2. Bata por 1 minuto, até obter uma bebida cremosa. 3. Despeje em copos altos. 4. Monte pequenos espetinhos alternando carambola, manga e cerejas e decore o copo. Sirva bem gelado.'),
('Blueberry Sparkler', 'BEBIDA', 4, 'Bebida refrescante, levemente cítrica e cheia de pequenas bolhas.', 'bebida_refrescante.png', 4.8, '25min', 'Fácil', 'Xarope: 1 xícara de mirtilos frescos; 1/2 xícara de açúcar; 1/2 xícara de água; 1 colher (chá) de gengibre fresco ralado; Casca de 1 limão; Bebida: 500ml de água com gás gelada; Gelo.', '1. Em uma panela, cozinhe os mirtilos, açúcar, água, gengibre e casca de limão em fogo médio por 10 min. 2. Coe a mistura e deixe esfriar. 3. Encha copos com gelo, adicione 3 a 4 colheres do xarope e complete com água com gás gelada. Misture delicadamente.'),
('Poção da Bruxa', 'BEBIDA', 1, 'Bebida quente, aromática e aconchegante que perfuma toda a cozinha com especiarias.', 'pocao_da_bruxa.png', 4.8, '25min', 'Média', '1 litro de sidra de maçã; 2 paus de canela; 1 laranja cortada em fatias finas; 2 anis-estrelados; 5 cravos-da-índia; 2 colheres (sopa) de mel (opcional).', '1. Em uma panela, coloque a sidra de maçã, canela, fatias de laranja, anis e cravos. 2. Aqueça em fogo baixo até liberar bastante aroma, sem ferver intensamente. 3. Deixe em infusão por 15-20 minutos. 4. Adicione mel, coe a bebida e sirva em canecas quentes.'),
('Parfait Conserta-Tudo', 'BEBIDA', 2, 'Uma sobremesa/bebida leve, refrescante e cheia de camadas coloridas de frutas.', 'parfait_frozen.png', 4.7, '15min', 'Fácil', '500g de iogurte grego natural; 1 xícara de morangos picados; 1/2 xícara de mirtilos; 1/2 xícara de framboesas; 1/2 xícara de nozes picadas tostadas; 2 colheres (sopa) de mel.', '1. Toste rapidamente as nozes em uma frigideira seca. 2. Em taças transparentes, coloque uma camada de iogurte grego. 3. Acrescente uma camada de frutas vermelhas. 4. Repita alternando até preencher. 5. Finalize com as nozes e regue com um fio de mel.'),
('Smoothie Relâmpago de Frutas Vermelhas', 'BEBIDA', 28, 'Smoothie refrescante, nutritivo e cheio de frutas vibrantes de alta velocidade.', 'smoothie_relampago.png', 4.9, '10min', 'Fácil', '200ml de chá verde descafeinado gelado; 1/2 xícara de mirtilos; 1/2 xícara de framboesas; 1 banana média; 1/2 xícara de abacaxi em cubos; 1 xícara de gelo; 1 colher (sopa) de mel.', '1. Prepare o chá verde descafeinado e deixe esfriar. 2. Coloque no liquidificador o chá verde, mirtilos, framboesas, banana, abacaxi, gelo e mel. 3. Bata por 1 minuto até ficar cremoso. Sirva em copos altos.'),
('Smoothie de Mirtilo e Hortelã do Buck', 'BEBIDA', 29, 'Smoothie de cor roxa vibrante com textura cremosa e nutritiva.', 'smoothie_buck.png', 4.8, '10min', 'Fácil', '1 xícara de mirtilos; 1/2 xícara de manga; 1/2 abacate pequeno; 1 colher (sopa) de chia; 1 colher (chá) de maca peruana; 1 colher (sopa) de mel; 1 colher (sopa) de manteiga de amêndoa; 250ml de leite de coco; 1 xícara de gelo picado.', '1. Coloque no liquidificador mirtilos, manga, abacate, chia, maca peruana, mel e manteiga de amêndoa. 2. Acrescente o leite de coco e o gelo. 3. Bata por 1 minuto até obter textura cremosa. Sirva e decore com folhas de hortelã.'),
('Toddy de Lava do Wu', 'BEBIDA', 30, 'Uma bebida quente, aconchegante e aromática parecida com lava vulcânica.', 'tody_de_lava.png', 4.7, '15min', 'Fácil', '300ml de suco de maçã com cranberry; 1 colher (sopa) de açúcar mascavo; 1 pitada de canela em pó; 1 pau de canela (opcional).', '1. Coloque o suco de maçã com cranberry em uma panela. 2. Acrescente o açúcar mascavo e a canela. 3. Aqueça em fogo baixo por cerca de 8 minutos, mexendo ocasionalmente. Não deixe ferver. Sirva em canecas quentes.'),
('Refrigerante Azul Gelado do Wei', 'BEBIDA', 30, 'Uma bebida leve, brilhante, gelada e super refrescante.', 'refrigeranteazul_wei.png', 4.8, '5min', 'Fácil', '300ml de club soda gelada; 4 colheres (sopa) de xarope de framboesa azul; Gelo a gosto.', '1. Encha um copo alto com bastante gelo. 2. Adicione o xarope de framboesa azul no fundo do copo. 3. Complete lentamente com a club soda gelada e misture delicadamente. Finalize com uma cereja.'),
('Milkshake Malévola: Dona do Mal', 'BEBIDA', 31, 'Milkshake com aparência misteriosa, tom verde vibrante e textura super cremosa.', 'milkshake_malevola.png', 5.0, '15min', 'Média', '4 bolas de sorvete de baunilha; 300ml de leite gelado; 1 colher (chá) de extrato de menta; Gotas de corante verde; Chantilly e raspas de chocolate para decorar.', '1. Bata no liquidificador o sorvete, o leite, o extrato de menta e o corante verde até ficar cremoso. 2. Despeje em copos altos. 3. Cubra com bastante chantilly (tingido de verde, se preferir) e finalize com raspas de chocolate.'),
('Néctar Perfeito de Fada', 'BEBIDA', 32, 'Néctar leve, refrescante e naturally adocicado com brilho de fada.', 'nécter_fada.png', 4.9, '10min', 'Fácil', '3 xícaras de melão sem sementes cortado em cubos; Suco de 1 limão; 2 colheres (sopa) de mel; 1/2 xícara de gelo.', '1. Coloque no liquidificador os cubos de melão, suco de limão e mel. 2. Acrescente gelo e bata por 1 minuto até obter mistura lisa e homogênea. Sirva imediatamente.'),
('Smoothie de Lama de Inseto', 'BEBIDA', 27, 'Bebida cremosa, refrescante e divertida, inspirada em Hakuna Matata.', 'smoothie_inseto_rei.leao.png', 4.8, '10min', 'Fácil', '1 xícara de frutas vermelhas congeladas; 170g de iogurte de baunilha; 200ml de leite desnatado; 1 banana média; 1/2 xícara de gelo.', '1. Coloque no liquidificador as frutas vermelhas, iogurte, leite, banana e gelo. 2. Bata por 1 minuto até ficar cremoso. 3. Despeje em copos e decore montando insetos com frutas pequenas por cima.'),
('Estrondo de Banana e Chocolate', 'BEBIDA', 10, 'Smoothie intenso e divertido, saboroso e cremoso.', 'smoothie_rei_louie.jpg', 5.0, '10min', 'Fácil', '2 bananas maduras; 4 tâmaras sem caroço; 2 colheres (sopa) de chocolate em pó; 250ml de leite de coco; 1 xícara de gelo; 2 colheres (sopa) de gotas de chocolate.', '1. Coloque no liquidificador bananas, tâmaras, chocolate em pó, leite de coco e gelo. 2. Bata até ficar cremoso. 3. Misture delicadamente as gotas de chocolate. Sirva com rodelas de banana.'),
('Smoothie Abacaxi e Manga do Mogli', 'BEBIDA', 10, 'Smoothie fresco e cheio de energia tropical explorando a selva.', 'smoothie_mogli.jpg', 4.8, '10min', 'Fácil', '1 xícara de manga congelada; 1 xícara de abacaxi congelado; 4 tâmaras sem caroço; 250ml de leite de coco; 1 xícara de gelo.', '1. Coloque todos os ingredientes no liquidificador. 2. Bata por cerca de 1 minuto até ficar cremoso. 3. Sirva imediatamente decorado com cubos de frutas e hortelã.'),
('Smoothie da Força do Julian', 'BEBIDA', 29, 'Smoothie encorpado, nutritivo e cheio de energia para recuperar as forças.', 'smoothie_força_julian.png', 4.9, '10min', 'Fácil', '1 folha de couve; 1 xícara de abacaxi; 2 colheres (sopa) de amêndoas; 1 banana; 1 colher (sopa) de mel; 170g de iogurte grego; 150ml de água gelada; 1 colher de pasta de amendoim; Gelo.', '1. Lave bem a folha de couve. 2. Coloque no liquidificador todos os ingredientes e bata por cerca de 1 minuto até ficar bem cremoso. Sirva em copos altos com amêndoas picadas.'),
('Smoothie de Cenoura do Diego', 'BEBIDA', 29, 'Smoothie alaranjado e vibrante com sabor refrescante de frutas e cenoura.', 'smoothie_cenoura_diego.png', 4.7, '10min', 'Fácil', 'Suco de 1/2 limão; 1 cenoura média picada; 200ml de suco de maçã; 170g de iogurte de baunilha; 1 xícara de lascas de gelo.', '1. Coloque no liquidificador o suco de limão, cenoura, suco de maçã, iogurte e gelo. 2. Bata por 1-2 minutos até obter uma mistura cremosa. 3. Coe se preferir mais liso e sirva decorado com fatias finas de maçã e cenoura.');
